<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(403);exit;}
function customer_id(string $id): string {if(!preg_match('/\A[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\z/',$id))throw new RuntimeException('Customer unavailable.');return $id;}
function customer_load(array $b,string $id): array {$rows=api('/rest/v1/business_customers?business_id=eq.'.rawurlencode($b['id']).'&environment=eq.'.profile_env().'&id=eq.'.customer_id($id).'&select=*',[],'GET',$_SESSION['auth']['access_token']);if(!$rows)throw new RuntimeException('Customer unavailable.');return $rows[0];}
function customer_search(array $b,string $search,int $page=1): array {if(!preg_match('//u',$search)||mb_len($search)>120)throw new RuntimeException('Search using up to 120 characters.');return profile_rpc('business_customer_search',['p_business'=>$b['id'],'p_environment'=>profile_env(),'p_search'=>trim($search),'p_page'=>$page]);}
function customer_values(): array {$d=[];foreach(['name'=>120,'email'=>254,'phone'=>40,'address'=>1000,'notes'=>2000] as $key=>$max){$s=$_POST[$key]??'';if(!is_string($s)||!preg_match('//u',$s)||mb_len(trim($s))>$max||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/',$s))throw new RuntimeException('Check customer details.');$d[$key]=trim($s);}if(mb_len($d['name'])<2)throw new RuntimeException('Enter the customer name.');if(($d['email']===''&&$d['phone']==='')||($d['email']!==''&&!filter_var($d['email'],FILTER_VALIDATE_EMAIL))||($d['phone']!==''&&(!preg_match('/\A[+0-9 ()-]{5,40}\z/',$d['phone'])||strlen(preg_replace('/\D/','',$d['phone']))<5)))throw new RuntimeException('Enter a valid customer email or phone.');return $d;}
// Selection is a GET navigation before entering a new document. No profile notes copied into customer agreements.
function customer_picker(array $b,string $file,string $search): void {echo '<details class="panel"'.($search!==''?' open':'').'><summary>Select an existing customer</summary><form method="get"><input type="hidden" name="new" value="1"><label for="customer_search">Search customers</label><input id="customer_search" name="customer_search" maxlength="120" value="'.esc($search).'"><button class="button secondary">Search customers</button></form><small>Select before entering quote or booking details.</small>';if($search!==''){try{$found=customer_search($b,$search);}catch(Throwable $e){echo '<p role="alert">Customer search unavailable. Please try again.</p></details>';return;}foreach(array_slice($found,0,20) as $c)echo '<p><a href="'.esc($file).'?new=1&amp;customer='.esc($c['id']).'">'.esc($c['details']['name']).'</a> · '.esc($c['details']['email']).' '.esc($c['details']['phone']).'</p>';if(!$found)echo '<p>No customers found.</p>';if(count($found)>20)echo '<p>More matches available. Refine your search.</p>';}echo '</details>';}
function customer_record_link(string $kind,array $r): void {if($r['customer_id']??null)echo '<p><a href="customers.php?id='.esc($r['customer_id']).'">Customer profile</a></p>';else echo '<p><a href="customers.php?link_kind='.esc($kind).'&amp;record='.esc($r['id']).'">Link customer profile</a></p>';}
